public class DOMNodePointer_getValue_TriageGen2Test {

    @Test
    public void testGetValue_WithTextNode() throws Exception {
        // Setup a real DOM structure to test the internal stringValue(node) logic
        Document doc = createDocument("<root>Hello World</root>");
        Node textNode = doc.getDocumentElement().getFirstChild();

        DOMNodePointer pointer = new DOMNodePointer(textNode, Locale.ENGLISH);

        Object value = pointer.getValue();

        assertEquals("Hello World", value);
    }









    private Document createDocument(String xml) throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        factory.setNamespaceAware(true);
        return factory.newDocumentBuilder().parse(new java.io.ByteArrayInputStream(xml.getBytes()));
    }
}

