        // For an Element node, stringValue typically returns the concatenation of all descendant text nodes
        Document doc = createDocument("<root><child>Content</child></root>");
        Node elementNode = doc.getDocumentElement().getChildNodes().item(0);

        DOMNodePointer pointer = new DOMNodePointer(elementNode, Locale.ENGLISH);

        Object value = pointer.getValue();

        assertEquals("Content", value);
    }







    private Document createDocument(String xml) throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        factory.setNamespaceAware(true);
        return factory.newDocumentBuilder().parse(new java.io.ByteArrayInputStream(xml.getBytes()));
    }
}

